import type { HistorySource } from "./kanab-quest-school-history-types";

export type ProductAtlasEntry = Readonly<{
  id: string;
  title: string;
  family: "seed" | "fibre" | "material" | "resin" | "extract" | "formulation" | "exposure" | "origin";
  plantPart: string;
  origin: string;
  principle: string;
  properties: readonly string[];
  limits: readonly string[];
  checks: readonly string[];
  regulationIds: readonly string[];
  sourceIds: readonly string[];
  relatedIds: readonly string[];
  established: "established" | "specific" | "prospective";
  marketEvidence: string;
}>;

export type ProductRegulation = Readonly<{
  id: string; title: string; territory: string; checkedAt: string;
  distinction: string; rule: string; appliesTo: readonly string[];
  limits: readonly string[]; sourceIds: readonly string[];
}>;

export type ProductFibreStage = Readonly<{
  id: string; title: string; input: string; transformation: string;
  outputs: readonly string[]; controls: readonly string[];
  limit: string; sourceIds: readonly string[];
}>;

const checkedAt = "2026-11-12";

function source(id: string, title: string, author: string, published: string, url: string, passage: string, limitation: string, access: HistorySource["access"] = "full-text"): HistorySource {
  return { id: `products-tool-${id}`, title, author, organization: author, published, url, passage, limitation, access, verifiedAt: checkedAt, documentKind: "Texte primaire juridique, institutionnel, scientifique ou de filière ; nature précisée dans le titre" };
}

